sys_ux_client_script.required_translations:
[
    {
        "message": "Remove entity type association"
    },
    {
        "message": "Delete entity from the entity class"
    },
    {
        "message": "Delete entity filter"
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    let tableName;
    let count = api.context.props.count;
    let entitytype = count == 1 ? 'entity type' : 'entity types';
    let associatedRecord = entitytype;
    let operationName = "remove";
    helpers.translate('Remove entity type association').then((val) => {
        api.setState('heading', val);
    });
    api.setState('operationLabel', 'Remove');
    switch (api.context.props.relatedListName) {
        case 'sn_grc_profile.profile_class':
            tableName = "entity class";
            associatedRecord = count == 1 ? "entity" : "entities";
            helpers.translate('Delete entity from the entity class').then((val) => {
                api.setState('heading', val);
            });
            api.setState('operationLabel', 'Delete');
            operationName = "delete";
            break;
        case 'sn_grc_enrichment_query.profile_type':
            tableName = "entity type";
            associatedRecord = count == 1 ? "entity filter" : "entity filters";
            helpers.translate('Delete entity filter').then((val) => {
                api.setState('heading', val);
            });
            api.setState('operationLabel', 'Delete');
            operationName = "delete";
            break;
        case 'sn_grc_m2m_profile_profile_type.profile_type':
            tableName = "entity type";
            associatedRecord = count == 1 ? "entity" : "entities";
            break;
        case 'sn_grc_m2m_profile_profile_type.profile':
            tableName = "entity";
            break;
        case "sn_risk_m2m_risk_definition_profile_type.sn_grc_profile_type":
            tableName = "entity type";
            associatedRecord = count == 1 ? "risk statement" : "risk statements";
            break;
        case "sn_risk_m2m_risk_definition_profile_type.statement":
            tableName = "risk statement";
            break;
        case "sn_risk_m2m_framework_profile_type.sn_grc_profile_type":
            tableName = "entity type";
            associatedRecord = count == 1 ? "risk framework" : "risk frameworks";
            break;
        case "sn_risk_m2m_framework_profile_type.sn_risk_framework":
            tableName = "risk framework";
            break;
        case "sn_compliance_m2m_policy_profile_type.sn_grc_profile_type":
            tableName = 'entity type';
            associatedRecord = count == 1 ? 'policy' : 'policies';
            break;
        case "sn_compliance_m2m_policy_profile_type.sn_compliance_policy":
            tableName = 'policy';
            break;
        case "sn_compliance_m2m_statement_profile_type.sn_grc_profile_type":
            tableName = "entity type";
            associatedRecord = count == 1 ? 'control objective' : 'control objectives';
            break;
        case "sn_compliance_m2m_statement_profile_type.sn_compliance_statement":
            tableName = "control objective";
            break;
    }

    if(api.context.props.relatedListName == 'sn_grc_enrichment_query.profile_type'){
        helpers
            .translate('Are you sure you want to {0} {1} {2}? After deletion, changes to the associated records (if any) will be reflected when the profile generation job runs.', [operationName, api.context.props.count, associatedRecord])
            .then((val) => {
                api.setState('deleteAndDeactivateMsg', val);
            });
    } else {
        helpers
            .translate('Are you sure you want to {0} {1} {2} from this {3}?', [operationName, api.context.props.count, associatedRecord, tableName])
            .then((val) => {
                api.setState('deleteAndDeactivateMsg', val);
            });
    }
    helpers
        .translate('{0}', ["This action will delete the following:"])
        .then((val) => {
            api.setState('deleteHeader', val);
        });
    helpers
        .translate('{0}', ["This action will deactivate/retire the following:"])
        .then((val) => {
            api.setState('deactivateRetireHeader', val);
        });
}
